 = 0 }\n            state.groups[entry[1]] = group\n        end\n        -- Emitters that fire together share one prediction; only the first of them redraws it.\n        if group.volley ~= entry[2] or TimeSince(group.t) > 500 then\n            local uuids = group.uuids\n            for i = #uuids, 1, -1 do\n                Argus.deleteTimedShape(uuids[i])\n                uuids[i] = nil\n            end\n            local delay = entry[3]\n            local timeout = delay > 0 and delay + 400 or 4000\n            local countdown = delay >= 1000 and AnyoneCore and AnyoneCore.addWorldTextCountdown\n            local drawer = TensorCore.getMoogleDrawer()\n            for _, s in ipairs(ljBlundervilleShapes[entry[2]]) do\n                if s[1] == 1 then\n                    uuids[#uuids + 1] = drawer:addTimedCircle(timeout, s[2], s[3], s[4], s[5])\n                elseif s[1] == 2 then\n                    uuids[#uuids + 1] = drawer:addTimedCenteredRect(timeout, s[2], s[3], s[4], s[5], s[6], s[7])\n                else\n                    uuids[#uuids + 1] = drawer:addTimedRect(timeout, s[2], s[3], s[4], s[5], s[6], s[7])\n                end\n                if countdown then\n                    if s.pos == nil then\n                        s.pos = { x = s[2], y = s[3], z = s[4] }\n                        if s[1] == 3 then\n                            -- Lines (sliders) also get a countdown at their far end.\n                            s.endPos = { x = s[2] + math.sin(s[7]) * s[5], y = s[3], z = s[4] + math.cos(s[7]) * s[5] }\n                        end\n                    end\n                    AnyoneCore.addWorldTextCountdown(delay, s.pos, 0xFFFFFFFF, true, 1)\n                    if s.endPos then\n                        AnyoneCore.addWorldTextCountdown(delay, s.endPos, 0xFFFFFFFF, true, 1)\n                    end\n                end\n            end\n            group.volley = entry[2]\n            group.t = Now()\n        end\n    end\nend\n\nself.used 