					{
						aType = "Lua",
						actionLua = "-- Stage 1: 34773 spinner grid. Light each hitbox (r5) while it spins, and when a set finishes its burst\n-- (8 volleys ~0.4s apart), draw that set's spinners with a countdown to their next spin (~3.3s rest, measured\n-- 2026-10-07). The 13 spinners form two sets that each keep their own rhythm. Event: OnEntityCast.\nlocal grid = ljBlundervilleGrid\nif grid == nil or grid.version ~= 1 then\n    grid = { version = 1, set = {}, emitters = { {}, {} } }\n    local sets = {\n        { { -10, -232 }, { -10, -222 }, { 0, -242 }, { 0, -202 }, { 10, -222 }, { 10, -212 } },\n        { { -10, -242 }, { -10, -212 }, { -10, -202 }, { 0, -222 }, { 10, -242 }, { 10, -232 }, { 10, -202 } },\n    }\n    for i, list in ipairs(sets) do\n        for _, p in ipairs(list) do\n            grid.set[p[1] .. \":\" .. p[2]] = i\n            grid.emitters[i][#grid.emitters[i] + 1] = { x = p[1], y = 10, z = p[2] }\n        end\n    end\n    ljBlundervilleGrid = grid\nend\n\nlocal state = data.ljBlunderville\nif state == nil then\n    state = { groups = {}, lanes = {} }\n    data.ljBlunderville = state\nend\nif state.gridLast == nil then\n    state.gridLast, state.gridVolleys = {}, {}\nend\n\nlocal ent = TensorCore.mGetEntity(eventArgs.entityID)\nif ent then\n    local p = ent.pos\n    local drawer = TensorCore.getMoogleDrawer()\n    drawer:addTimedCircle(600, p.x, p.y, p.z, 5)\n\n    local set = grid.set[math.floor(p.x + 0.5) .. \":\" .. math.floor(p.z + 0.5)]\n    if set then\n        local last = state.gridLast[set]\n        local since = last and TimeSince(last) or 99999\n        if since > 1000 then\n            state.gridVolleys[set] = 1\n        elseif since > 150 then\n            state.gridVolleys[set] = state.gridVolleys[set] + 1\n            if state.gridVolleys[set] == 8 then\n                local countdown = AnyoneCore and AnyoneCore.addWorldTextCountdown\n                for _, e in ipairs(grid.emitters[set]) do\n                    drawer:addTimedCircle(3300, e.x, e.y, e.z, 5)\n                    if countdown then\n                        AnyoneCore.addWorldTextCountdown(3300, e, 0xFFFFFFFF, true, 1)\n                    end\n                end\n            end\n        end\n        state.gridLast[set] = Now()\n    end\nend\n\nself.used = true\n",
